    void record(const std::string& message) {
        std::ofstream file(log_file, std::ios_base::app); // 以追加模式打开文件
        time_t now = time(nullptr);                      // 获取当前时间
        tm* ltm = localtime(&now);                       // 将时间转换为本地时间结构体

        // 写入日志，包含时间和消息
        file << "[" << asctime(ltm) << " " << message << "\n";
    }
};

class DataCleaner {
private:
    // 数据记录的结构体，包含必要字段
    struct Record {
        int id;             // 唯一标识符
        std::string content; // 文本内容
        std::string created_at; // 创建时间
        std::string responded_at; // 响应时间
    };

public:
    // 数据清洗的主函数，对数据进行去重、缺失值处理和时间格式统一
    void clean(std::vector<Record>& data) {
        // 1. 去重：基于唯一标识符id
        // 使用std::unique算法实现去重，并使用lambda表达式作为比较函数
        auto duplicate_ids = [](const Record& a, const Record& b) { return a.id == b.id; };
        std::sort(data.begin(), data.end(), duplicate_ids); // 先排序，使相同的id相邻
        auto last = std::unique(data.begin(), data.end(), duplicate_ids); // 执行去重
        data.erase(last, data.end());                       // 移除重复元素

        // 2. 处理缺失值：删除包含空内容、创建时间和响应时间的记录
        for (auto it = data.begin(); it != data.end(); ) {
            if (it->content.empty() || it->created_at.empty() || it->responded_at.empty()) {
                it = data.erase(it); // 删除不符合条件的记录
            } else {
                ++it;              // 继续下一个元素
            }
        }

        // 3. 统一时间格式：将所有时间字段转换为ISO标准格式（YYYY-MM-DDTHH:MM:SS）
        for (auto& record : data) {
            std::stringstream ss(record.created_at); // 使用 stringstream 解析字符串
            tm time_struct = {};                      // 创建tm结构体
            ss >> time_struct.tm_year >> time_struct.tm_mon >> time_struct.tm_mday >>
                time_struct.tm_hour >> time_struct.tm_min >> time_struct.tm_sec;
            time_struct.tm_isdst = -1; // 设置 daylight savings time 标志为-1（未知）

            char buffer[20];             // 缓冲区用于存储格式化后的时间字符串
            std::strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &time_struct);
            record.created_at = std::string(buffer); // 更新创建时间

            // 处理 responded_at 类似，假设字段存在且格式一致
            ss.str(record.responded_at);
            ss >> time_struct.tm_year >> time_struct.tm_mon >> time_struct.tm_mday >>
                time_struct.tm_hour >> time_struct.tm_min >> time_struct.tm_sec;
            std::strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &time_struct);
            record.responded_at = std::string(buffer);
        }
    }
};

int main() {
    // 主程序入口，执行数据处理的整个流程

    LogRecorder recorder(Config::LOG_FILE); // 初始化日志记录器
    recorder.record("Processing started");   // 记录处理开始的时间

    // 1. 获取指定目录下的所有CSV和JSON文件
    std::vector<std::string> files;
    for (const auto& entry : std::filesystem::directory_iterator(Config::DATA_DIR)) {
        const std::string filename = entry.path().filename();
        if (filename.ends_with(".csv") || filename.ends_with(".json")) { // 判断文件扩展名
            files.push_back(filename);
        }
    }

    size_t total_files = files.size(); // 获取总文件数

    // 2. 遍历所有文件进行处理
    for (size_t i = 0; i < total_files; ++i) {
        std::string file = files[i];
        recorder.record("Processing file " + std::to_string(i + 1) + "/" + std::to_string(total_files) + ": " + file); // 记录当前处理的文件

        DataCleaner cleaner;
        std::vector<DataCleaner::Record> data;

        // 假设读取文件逻辑（此处未完全实现，需根据具体文件格式添加）
        // 这里仅展示数据清洗部分，实际应用中需要完整的文件读取和处理逻辑
        cleaner.clean(data);

        recorder.record("Processed file: " + file); // 记录文件处理完成
    }

    recorder.record("Processing finished");          // 记录处理完成时间
    return 0;
}
